<template>
  <div class="loading-component loading-background">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';

const $ = document.querySelector.bind(document);

export default defineComponent({
  el: '#app',
  name: 'Loader',
  props: ['show', 'hide', 'zIndex'],
  data() {
    return {};
  },
  watch: {
    show() {
      this.showLoader();
    },
    hide() {
      this.hideLoader();
    },
    zIndex() {
      ($('.loading-component') as HTMLElement).style.zIndex = this.zIndex;
    },
  },
  methods: {
    showLoader() {
      ($('.loading-component') as HTMLElement).style.display = 'block';
    },
    hideLoader() {
      ($('.loading-component') as HTMLElement).style.display = 'none';
    },
  },
});
</script>

